<script setup>
import {ref,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api,session,errorText} from '../auth/api.js'
import {price,types,states,mapUrl,query} from './property.js'
import AppShell from '../../components/layout/AppShell.vue'
import PrivateImage from '../../components/PrivateImage.vue'
const route=useRoute(),router=useRouter(),p=ref(null),managed=ref(null),busy=ref(false),error=ref(''),notice=ref(''),pois=ref([]),poiError=ref(''),radius=ref(1000),active=ref(0)
const own=computed(()=>route.query.own==='1');let run=0
async function load(){const generation=++run;busy.value=true;error.value='';p.value=null;pois.value=[];try{const result=await api((own.value?'/users/me/properties/':'/properties/')+route.params.id,{authenticated:!!session.token});if(generation===run){managed.value=own.value?result:null;p.value=own.value?result.property:result;active.value=0;if(!own.value)await nearby()}}catch(e){if(generation===run)error.value=errorText(e)}finally{if(generation===run)busy.value=false}}
async function nearby(){const id=route.params.id;poiError.value='';try{const result=await api('/properties/'+id+'/points-of-interest?'+query({radiusMeters:radius.value,limit:20}),{authenticated:!!session.token});if(route.params.id===id)pois.value=result}catch(e){if(route.params.id===id)poiError.value=errorText(e)}}
async function save(){if(!session.token)return router.push('/login');try{await api('/users/me/saved-properties/'+p.value.id,{method:'PUT'});notice.value='Đã lưu tin.'}catch(e){error.value=errorText(e)}}
watch(()=>[route.params.id,own.value],load,{immediate:true})
</script>
<template><AppShell><RouterLink to="/listings">← Danh sách tin</RouterLink><p v-if="busy" role="status">Đang tải chi tiết…</p><p v-if="error" role="alert" class="sp-error">{{error}} <button @click="load">Tải lại</button></p><p v-if="notice" role="status" class="sp-success">{{notice}}</p>
<template v-if="p"><div class="sp-panel"><span class="sp-tag">{{types[p.propertyType]}} · {{states[p.status]}}</span><h1>{{p.title}}</h1><p class="sp-muted">{{p.address}} · {{[p.ward,p.district,p.city].filter(Boolean).join(', ')}}</p><h2>{{price(p)}}</h2><div class="sp-row"><span>{{p.areaSqm}} m²</span><span>{{p.bedrooms??'—'}} phòng ngủ</span><span>{{p.bathrooms??'—'}} phòng tắm</span><button v-if="!own" @click="save">Lưu yêu thích</button><RouterLink v-if="!own" class="sp-btn" :to="'/listing/'+p.id+'/report'">Báo cáo tin</RouterLink><RouterLink v-if="own&&p.status!=='HIDDEN'" class="sp-btn" :to="{path:'/post',query:{edit:p.id}}">Chỉnh sửa tin</RouterLink></div></div>
<div class="sp-two"><div><div class="sp-panel"><PrivateImage class="sp-cover" style="height:380px" :src="p.images[active]?.url" :alt="p.title"/><div class="sp-row" style="margin-top:14px"><button v-for="(image,index) in p.images" :key="image.id" @click="active=index" :aria-pressed="active===index">Ảnh {{index+1}}{{image.cover?' · Bìa':''}}</button></div></div><section class="sp-panel"><h2>Mô tả</h2><p class="sp-pre">{{p.description||'Chưa có mô tả.'}}</p><h3>Tiện ích được khai báo</h3><div class="sp-row"><span v-for="a in p.declaredAmenities" :key="a" class="sp-tag">{{a}}</span><span v-if="!p.declaredAmenities.length" class="sp-muted">Chưa có thông tin.</span></div></section></div><aside><section class="sp-panel"><h2>Vị trí</h2><iframe class="sp-map" :src="mapUrl(p)" title="Vị trí bất động sản" loading="lazy" referrerpolicy="no-referrer"></iframe></section><section v-if="managed" class="sp-panel"><h2>Thông tin liên hệ của bạn</h2><p>{{managed.contactName||'Chưa cung cấp'}}</p><p>{{managed.contactPhone}}</p><p>{{managed.contactEmail}}</p></section></aside></div>
<section v-if="!own" class="sp-panel"><h2>Tiện ích xung quanh</h2><form class="sp-row" @submit.prevent="nearby"><label for="radius">Bán kính (m)</label><input id="radius" v-model="radius" type="number" min="1" max="50000" required><button>Cập nhật</button></form><p v-if="poiError" role="alert" class="sp-error">{{poiError}}</p><p v-else-if="!pois.length" class="sp-muted">Chưa có tiện ích trong bán kính này.</p><ul><li v-for="poi in pois" :key="poi.id">{{poi.name}} · {{poi.category}} · {{Math.round(poi.distanceMeters)}} m</li></ul></section>
</template></AppShell></template>